`Schema` struct for:

- Validating `Message`s against existing schemas
- Creating and validating `Message`s

`SchemaBuilder` struct for:

- Programmatically building CDDL schemas

## Schema from string
```rs
// Create "person" schema from cddl string
let cddl_str = "person = { (
    age: { type: \"int\", value: int }, 
    name: { type: \"str\", value: tstr } 
) }";
let person = Schema::new(&Hash::new(USER_SCHEMA_HASH).unwrap(), cddl_str);
```
## Schema builder
```rs
// Create new empty schema named "person"
let mut person = SchemaBuilder::new("person".to_owned());

// Add two message fields to the schema
person
    .add_message_field("name".to_owned(), Type::Tstr)
    .unwrap();
person
    .add_message_field("age".to_owned(), Type::Int)
    .unwrap();
```
## Validate MessageFields
```rs
  // Create a "person" message
  let mut me = MessageFields::new();
  me.add("name", MessageValue::Text("Sam".to_owned()))
      .unwrap();
  me.add("age", MessageValue::Integer(35)).unwrap();

  // Validate message fields against person schema
  let me_bytes = serde_cbor::to_vec(&me).unwrap();
  assert!(person.validate_message(me_bytes.clone()).is_ok());
```
## Create and validate Message
```rs

let cddl_str = "person = { (
    age: { type: \"int\", value: int }, 
    name: { type: \"str\", value: tstr } 
) }";

let person = Schema::new(&Hash::new(USER_SCHEMA_HASH).unwrap(), cddl_str);

let valid_message = person
    .create(vec![
        ("name", MessageValue::Text("Panda".to_string())),
        ("age", MessageValue::Integer(12)),
    ])
 .unwrap();

```

